interface PaymentGateway {
  charge(amount: number): Promise<void>;
}

class OrderService {
  // Dependency supplied from outside — OrderService doesn't know or care which implementation
  constructor(private gateway: PaymentGateway) {}

  async placeOrder(order: Order) {
    return this.gateway.charge(order.total);
  }
}

// Production
const orderService = new OrderService(new StripeGateway());

// Test — a lightweight fake, no real network calls
const fakeGateway = { charge: jest.fn() };
const testService = new OrderService(fakeGateway);
